// newInput builds the insert a Batch queues for in under parent, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLEventRepository) newInput(parent string, in *eventv1.Event) (resourceql.CreateInput, *eventv1.Event, error) {
	var ci resourceql.CreateInput
	parentIDs, err := repox.SplitName(parent, "calendars")
	if err != nil {
		return ci, nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "calendars", "events")
		if err != nil {
			return ci, nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return ci, nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*eventv1.Event)
	in.Name = FormatEventName(parentIDs[0], id)
	id = rowID // keyed as Create keys it
	ci = eventToCreateInput(in)
	ci.Id = id
	ci.CalendarId = parentIDs[0]
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	ci.UpdateTime = now
	return ci, in, nil
}

